#!/usr/bin/env bash
#
# This is a STARTING POINT, not an answer. Copy the whole EXAMPLE folder to
# submissions/<your-github-username>/ and work in your copy.
#
# Do not edit this file. It is ignored when marking.

set -euo pipefail

dir="${1:?usage: report.sh <directory>}"

file_count=$(find "$dir" -type f | wc -l)
dir_count=$(find "$dir" -mindepth 1 -type d | wc -l)

echo "FILES: $file_count"
echo "DIRS: $dir_count"

echo "LARGEST:"
find "$dir" -type f -printf '%s %p\n' | sort -nr | head -3 | sed "s| $dir/| |"
echo "EXECUTABLE:"
find "$dir" -type f -perm -u=x | sed "s|^$dir/||" | sort
echo "EXTENSIONS:"
find "$dir" -type f | sed -n 's/.*\(\.[^./]*\)$/\1/p' | sort | uniq -c | sort -nr | head -5
